#!/usr/bin/env python3
"""The check for codegen/t1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("the generated records match the schema", *ws.run([sys.executable, "tools/gen_records.py", "--check"]))
    ws.check("the schema declares the field", re.search('^\\s+billing_email:\\s*str\\?', ws.read("schema/records.def"), re.M) is not None)
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally._generated.records import Customer\nfrom tally_api.serializers import customer_json\nc = Customer("C-1", "Acme", "a@acme.io", "GB", billing_email="ap@acme.io")\nassert Customer.from_row(c.to_row()).billing_email == "ap@acme.io"\nassert Customer("C-2", "B", "b@b.io", "GB").billing_email is None\nassert customer_json(c)["billingEmail"] == "ap@acme.io"', env=None))


if __name__ == "__main__":
    main(check)
